files.styles/app.css:
/* Disciplined usage: every value comes back through a token. None of these
   references is a value, and counting them as values is what once made
   Polaris look like it had 49 radii. */
.card {
  background: var(--bg);
  color: var(--fg);
  border-radius: var(--radius-lg);
  font-size: var(--text-body);
}
.chip {
  border-radius: var(--radius-sm);
  font-size: inherit;
}
/* one genuine stray, so the fixture is not all virtue */
.badge { background: #ff0055; border-radius: 3px; }

files.styles/tokens.css:
/* A system with both variant axes: a theme switch and a density switch.
   Every token below is stated three times. The palette is 4 colours, not 10,
   and the radius scale is 2 values, not 6. */
:root {
  --bg: #ffffff;
  --fg: #101010;
  --brand: #2563eb;
  --radius-sm: 4px;
  --radius-lg: 8px;
}
.dark {
  --bg: #101010;
  --fg: #f5f5f5;
  --brand: #60a5fa;
}
[data-density="compact"] {
  --radius-sm: 2px;
  --radius-lg: 6px;
}
[data-density="spacious"] {
  --radius-sm: 6px;
  --radius-lg: 12px;
}
